#!/bin/bash
# =====================================================================
#  Eatravel + Airtable
#  1. Crea in Airtable (base "App Cibi") le tabelle Cities e Dishes
#     con tutti i dati che l'app ha già (5 città, 76 piatti).
#  2. Collega l'app ad Airtable SENZA cambiare l'interfaccia.
#  Uso:  bash integra_airtable.sh
# =====================================================================

echo ""
echo "=== Eatravel + Airtable ==="
echo ""

# ---------- 1. Trova il progetto Xcode ----------
echo "→ Cerco il progetto Eatravel (qualche secondo)..."
TROVATI=()
while IFS= read -r f; do
  d="$(dirname "$(dirname "$f")")"
  [ -d "$d/Eatravel.xcodeproj" ] && TROVATI+=("$d")
done < <(find ~ -name EatravelApp.swift -not -path '*/Library/*' -not -path '*/.Trash/*' -not -path '*Eatravel_backup*' 2>/dev/null)

if [ ${#TROVATI[@]} -eq 0 ]; then
  echo "❌ Non trovo il progetto Eatravel (cartella con Eatravel.xcodeproj)."; exit 1
elif [ ${#TROVATI[@]} -eq 1 ]; then
  PROJ="${TROVATI[0]}"
else
  echo "Ho trovato più copie del progetto:"
  for i in "${!TROVATI[@]}"; do echo "  $((i+1))) ${TROVATI[$i]}"; done
  read -r -p "Scrivi il numero di quella che usi in Xcode: " N
  PROJ="${TROVATI[$((N-1))]}"
  [ -z "$PROJ" ] && { echo "❌ Numero non valido."; exit 1; }
fi
SRC="$PROJ/Eatravel"
echo "✅ Progetto: $PROJ"

# ---------- 2. Token e Base ID ----------
CONF="$HOME/Downloads/AirtableCibi/Swift/AirtableConfig.swift"
TOKEN=""; BASE_ID=""
if [ -f "$CONF" ]; then
  TOKEN=$(grep -oE 'pat[A-Za-z0-9]{10,}\.[a-f0-9]{20,}' "$CONF" | head -1)
  BASE_ID=$(grep -oE 'app[A-Za-z0-9]{14}' "$CONF" | head -1)
fi
[ -z "$TOKEN" ] && read -r -p "Incolla il Personal Access Token (pat...): " TOKEN
[ -z "$BASE_ID" ] && read -r -p "Incolla il Base ID (app...): " BASE_ID
TOKEN=$(echo "$TOKEN" | tr -d '[:space:]'); BASE_ID=$(echo "$BASE_ID" | tr -d '[:space:]')
[[ "$TOKEN" != pat* ]] && { echo "❌ Token non valido."; exit 1; }
[[ "$BASE_ID" != app* ]] && { echo "❌ Base ID non valido."; exit 1; }
echo "✅ Uso la base $BASE_ID"

TMP=$(mktemp -d)
cat > "$TMP/t_cities.json" << 'EATRAVEL_EOF'
{"name": "Cities", "description": "Cities shown in the Eatravel carousel. Order = position in the carousel.", "fields": [{"name": "City ID", "type": "singleLineText", "description": "Unique lowercase id, e.g. napoli. Dishes use it in their City ID field."}, {"name": "Name", "type": "singleLineText"}, {"name": "Country", "type": "singleLineText"}, {"name": "Subtitle", "type": "singleLineText"}, {"name": "Image URL", "type": "url", "description": "https link to the city photo"}, {"name": "Latitude", "type": "number", "options": {"precision": 4}}, {"name": "Longitude", "type": "number", "options": {"precision": 4}}, {"name": "Order", "type": "number", "options": {"precision": 0}}]}
EATRAVEL_EOF
cat > "$TMP/t_dishes.json" << 'EATRAVEL_EOF'
{"name": "Dishes", "description": "Dishes of the Eatravel app. Nutrition values are for one serving.", "fields": [{"name": "Dish ID", "type": "singleLineText", "description": "Unique lowercase id, e.g. napoli-genovese"}, {"name": "Name", "type": "singleLineText"}, {"name": "City ID", "type": "singleSelect", "options": {"choices": [{"name": "london"}, {"name": "napoli"}, {"name": "paris"}, {"name": "madrid"}, {"name": "vienna"}]}, "description": "Must match a City ID in the Cities table"}, {"name": "Category", "type": "singleSelect", "options": {"choices": [{"name": "Street Food"}, {"name": "Main Dishes"}, {"name": "Sweets"}, {"name": "Local Specialties"}]}}, {"name": "Description", "type": "multilineText"}, {"name": "Photo", "type": "multipleAttachments", "description": "Optional: if present it replaces Image URL"}, {"name": "Image URL", "type": "url"}, {"name": "Minutes", "type": "number", "options": {"precision": 0}}, {"name": "Ingredients", "type": "multilineText", "description": "One ingredient per line"}, {"name": "Steps", "type": "multilineText", "description": "One step per line"}, {"name": "Calories (kcal)", "type": "number", "options": {"precision": 0}}, {"name": "Protein (g)", "type": "number", "options": {"precision": 0}}, {"name": "Carbs (g)", "type": "number", "options": {"precision": 0}}, {"name": "Fat (g)", "type": "number", "options": {"precision": 0}}, {"name": "Fiber (g)", "type": "number", "options": {"precision": 1}}, {"name": "Sugar (g)", "type": "number", "options": {"precision": 1}}, {"name": "Sodium (mg)", "type": "number", "options": {"precision": 0}}, {"name": "Order", "type": "number", "options": {"precision": 0}}]}
EATRAVEL_EOF
cat > "$TMP/r_cities_0.json" << 'EATRAVEL_EOF'
