{"typecast": true, "records": [{"fields": {"Dish ID": "london-sunday-roast-with-yorkshire-pudding", "Name": "Sunday Roast with Yorkshire pudding", "City ID": "london", "Category": "Main Dishes", "Description": "Discover Sunday Roast with Yorkshire pudding in London. A simplified preparation is included below.", "Image URL": "https://blog.resy.com/wp-content/uploads/2021/09/1600x1600-77-1-2000x1125.jpeg", "Minutes": 80, "Ingredients": "150 g beef roasting joint portion\n150 g potatoes\n100 g carrots\n1 small ready-made Yorkshire pudding\n40 ml gravy\n10 g oil", "Steps": "Roast the beef, potatoes and carrots, adjusting cooking time to the size of the joint and checking doneness.\nRest the meat before slicing.\nHeat the Yorkshire pudding according to its package and serve everything with hot gravy.", "Calories (kcal)": 680.0, "Protein (g)": 43.0, "Carbs (g)": 60.0, "Fat (g)": 29.0, "Fiber (g)": 7.0, "Sugar (g)": 8.0, "Sodium (mg)": 850.0, "Order": 21}}, {"fields": {"Dish ID": "london-shepherd-s-cottage-pie", "Name": "Shepherd's / Cottage Pie", "City ID": "london", "Category": "Main Dishes", "Description": "Discover Shepherd's / Cottage Pie in London. A simplified preparation is included below.", "Image URL": "https://www.hairybikers.com/uploads/images/_recipeImage/76974/Shepherds-pie.jpg", "Minutes": 60, "Ingredients": "120 g minced lamb or beef\n200 g potatoes\n80 g carrots and onion\n80 g passata\n30 ml milk\n5 g butter", "Steps": "Boil and mash the potatoes with milk and butter.\nBrown the mince, add chopped vegetables and passata and simmer for 20 minutes.\nLamb makes shepherd's pie; beef makes cottage pie.\nTransfer to a small baking dish, top with mash and bake at 200 °C for about 20 minutes until golden and piping hot.", "Calories (kcal)": 590.0, "Protein (g)": 33.0, "Carbs (g)": 51.0, "Fat (g)": 27.0, "Fiber (g)": 7.0, "Sugar (g)": 11.0, "Sodium (mg)": 520.0, "Order": 22}}, {"fields": {"Dish ID": "london-chicken-tikka-masala", "Name": "Chicken Tikka Masala", "City ID": "london", "Category": "Main Dishes", "Description": "Discover Chicken Tikka Masala in London. A simplified preparation is included below.", "Image URL": "https://images.squarespace-cdn.com/content/v1/5ea5f3913b0ccf06d0ec2563/1611509313644-39XMQ3PEHX9DW4BA71JA/Chicken+Tikka+Masala+%2828%29.jpg", "Minutes": 45, "Ingredients": "150 g chicken\n50 g plain yogurt\n100 g passata\n40 g onion\n30 ml cream\n10 g oil\nGaram masala\n60 g dry rice", "Steps": "Coat diced chicken with yogurt and garam masala.\nCook in oil until browned, then add chopped onion, passata and cream.\nSimmer until the chicken is fully cooked, about 15–20 minutes.\nCook the rice separately and serve together.", "Calories (kcal)": 690.0, "Protein (g)": 43.0, "Carbs (g)": 67.0, "Fat (g)": 28.0, "Fiber (g)": 4.0, "Sugar (g)": 10.0, "Sodium (mg)": 620.0, "Order": 23}}, {"fields": {"Dish ID": "london-full-english-breakfast", "Name": "Full English Breakfast", "City ID": "london", "Category": "Main Dishes", "Description": "Discover Full English Breakfast in London. A simplified preparation is included below.", "Image URL": "https://iamafoodblog.com/wp-content/uploads/2019/02/full-english-7355w-2.jpg", "Minutes": 30, "Ingredients": "1 egg\n1 pork sausage\n1 bacon rasher\n80 g baked beans\n80 g mushrooms\nHalf a tomato\n1 slice toast", "Steps": "Cook the sausage and bacon thoroughly.\nFry or grill the mushrooms and tomato and warm the beans.\nCook the egg to your liking and serve with the toast and other components.", "Calories (kcal)": 710.0, "Protein (g)": 36.0, "Carbs (g)": 48.0, "Fat (g)": 41.0, "Fiber (g)": 8.0, "Sugar (g)": 12.0, "Sodium (mg)": 1500.0, "Order": 24}}, {"fields": {"Dish ID": "london-scones-with-clotted-cream-and-jam", "Name": "Scones with clotted cream and jam", "City ID": "london", "Category": "Sweets", "Description": "Discover Scones with clotted cream and jam in London. A simplified preparation is included below.", "Image URL": "https://www.momlovesbaking.com/wp-content/uploads/2019/12/Cream-Scones-SQ2.jpg", "Minutes": 30, "Ingredients": "60 g self-raising flour\n10 g butter\n30 ml milk\n10 g sugar\n25 g clotted cream\n20 g jam", "Steps": "Rub butter into flour, stir in sugar and milk and gently form a thick dough.\nCut into rounds.\nBake at 200 °C for 12–15 minutes until risen and golden.\nSplit and serve with clotted cream and jam.", "Calories (kcal)": 470.0, "Protein (g)": 7.0, "Carbs (g)": 62.0, "Fat (g)": 22.0, "Fiber (g)": 2.0, "Sugar (g)": 29.0, "Sodium (mg)": 370.0, "Order": 25}}, {"fields": {"Dish ID": "london-sticky-toffee-pudding", "Name": "Sticky Toffee Pudding", "City ID": "london", "Category": "Sweets", "Description": "Discover Sticky Toffee Pudding in London. A simplified preparation is included below.", "Image URL": "https://meltchocolates.com/wp-content/uploads/2023/07/sticky-toffee-pudding-scaled.jpg", "Minutes": 45, "Ingredients": "35 g chopped dates\n35 g flour\nHalf a beaten egg\n20 g butter\n25 g brown sugar\n20 ml cream\nA pinch of baking powder", "Steps": "Soak dates in a little hot water, mash and combine with flour, egg, half the butter, half the sugar and baking powder.\nBake in a buttered ramekin at 180 °C for about 25 minutes.\nWarm the remaining butter and sugar with the cream until smooth and spoon over the pudding.", "Calories (kcal)": 490.0, "Protein (g)": 6.0, "Carbs (g)": 66.0, "Fat (g)": 24.0, "Fiber (g)": 3.0, "Sugar (g)": 45.0, "Sodium (mg)": 180.0, "Order": 26}}, {"fields": {"Dish ID": "london-victoria-sponge", "Name": "Victoria Sponge", "City ID": "london", "Category": "Sweets", "Description": "Discover Victoria Sponge in London. A simplified preparation is included below.", "Image URL": "https://ichef.bbc.co.uk/ace/standard/1600/food/recipes/mary_berrys_perfect_34317_16x9.jpg.webp", "Minutes": 35, "Ingredients": "30 g self-raising flour\n30 g butter\n30 g sugar\nHalf a beaten egg\n15 g jam\n20 ml whipped cream", "Steps": "Beat butter and sugar, then mix in egg and flour.\nDivide between two small cake tins and bake at 180 °C until springy, about 15–20 minutes.\nCool completely and sandwich with jam and whipped cream.", "Calories (kcal)": 510.0, "Protein (g)": 5.0, "Carbs (g)": 60.0, "Fat (g)": 29.0, "Fiber (g)": 1.0, "Sugar (g)": 42.0, "Sodium (mg)": 240.0, "Order": 27}}, {"fields": {"Dish ID": "london-pie-and-mash", "Name": "Pie and mash", "City ID": "london", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT98P-2qH8osV8DWQU4Ief4qMOCcKnhZCPoro2l6LwPlY4LKnU3JVdCPlpJ&s=10", "Minutes": 65, "Ingredients": "100 g beef mince\n80 g pastry\n200 g potatoes\n40 g onion\n100 ml beef stock\n10 g flour\nParsley", "Steps": "Brown the beef and onion, stir in half the flour and add half the stock. Simmer until thick.\nLine a small pie dish with pastry, add cooled filling, cover with pastry and cut a steam vent. Bake at 200 °C until golden and piping hot.\nBoil and mash the potatoes. Simmer the remaining stock with the remaining flour and parsley to make a sauce; serve with the pie.", "Calories (kcal)": 790.0, "Protein (g)": 32.0, "Carbs (g)": 85.0, "Fat (g)": 34.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 28}}, {"fields": {"Dish ID": "london-bangers-and-mash", "Name": "Bangers and mash", "City ID": "london", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://www.eatingeurope.com/wp-content/uploads/2025/11/Gravy_with_bangers_and_mash_London-2.jpg", "Minutes": 40, "Ingredients": "150 g pork sausages\n200 g potatoes\n80 g onion\n100 ml stock\n10 g butter\n5 g flour", "Steps": "Cook the sausages thoroughly according to their pack instructions.\nBoil the potatoes until tender and mash with butter.\nSoften sliced onion, stir in flour and stock and simmer until thickened. Serve over the sausages and mash.", "Calories (kcal)": 720.0, "Protein (g)": 28.0, "Carbs (g)": 60.0, "Fat (g)": 39.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 29}}, {"fields": {"Dish ID": "london-bubble-and-squeak", "Name": "Bubble and squeak", "City ID": "london", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://hips.hearstapps.com/hmg-prod/images/del-bubble-squeak-64ac03beb1dce.jpg?crop=0.667xw:1.00xh;0.125xw,0&resize=1200:*", "Minutes": 25, "Ingredients": "180 g cooked potatoes\n100 g cooked cabbage\n40 g onion\n10 g butter\n1 egg", "Steps": "Mash the cooked potatoes and finely chop the cooked cabbage and onion.\nSoften onion in butter, add potatoes and cabbage and press into a thick cake.\nCook until browned, turn carefully and brown the other side. Serve with a freshly cooked egg.", "Calories (kcal)": 410.0, "Protein (g)": 13.0, "Carbs (g)": 43.0, "Fat (g)": 20.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 30}}]}
