{"typecast": true, "records": [{"fields": {"Dish ID": "madrid-bartolillos", "Name": "Bartolillos", "City ID": "madrid", "Category": "Sweets", "Description": "Discover Bartolillos in Madrid. A simplified preparation is included below.", "Image URL": "https://www.fascinatingspain.com/media/fascinatingspain/images/2021/04/19/20210419105457296266.jpg", "Minutes": 45, "Ingredients": "70 g pastry dough\n80 ml milk\nHalf an egg yolk\n10 g cornflour\n15 g sugar\nLemon zest\nFrying oil", "Steps": "Whisk milk, yolk, cornflour, sugar and zest together and cook gently, stirring, until thick.\nCool the custard.\nFill small pastry rounds with custard, seal firmly and fry until golden.\nDrain before serving.", "Calories (kcal)": 460.0, "Protein (g)": 7.0, "Carbs (g)": 58.0, "Fat (g)": 23.0, "Fiber (g)": 2.0, "Sugar (g)": 22.0, "Sodium (mg)": 230.0, "Order": 41}}, {"fields": {"Dish ID": "madrid-torrijas", "Name": "Torrijas", "City ID": "madrid", "Category": "Sweets", "Description": "Discover Torrijas in Madrid. A simplified preparation is included below.", "Image URL": "https://www.inmsol.com/wp-content/uploads/2011/02/Torrijas.jpg", "Minutes": 20, "Ingredients": "70 g day-old bread\n100 ml milk\n1 egg\n10 g sugar\nCinnamon\n10 g olive oil", "Steps": "Warm the milk with cinnamon and let it cool.\nBriefly soak thick bread slices in the milk.\nDip in beaten egg and pan-fry until golden and the egg coating is cooked.\nFinish with sugar and cinnamon.", "Calories (kcal)": 410.0, "Protein (g)": 15.0, "Carbs (g)": 50.0, "Fat (g)": 17.0, "Fiber (g)": 2.0, "Sugar (g)": 20.0, "Sodium (mg)": 350.0, "Order": 42}}, {"fields": {"Dish ID": "madrid-huevos-rotos-con-jamon", "Name": "Huevos rotos con jamón", "City ID": "madrid", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://doeatbetterexperience.com/wp-content/uploads/2026/06/huevos-rotos-recipe.jpg", "Minutes": 30, "Ingredients": "250 g potatoes\n2 eggs\n40 g sliced ham\n15 g olive oil", "Steps": "Peel and cut the potatoes into batons.\nCook the potatoes in oil until tender and golden, then drain.\nFry the eggs and place over the potatoes with ham. Break the eggs just before serving.", "Calories (kcal)": 650.0, "Protein (g)": 27.0, "Carbs (g)": 54.0, "Fat (g)": 35.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 43}}, {"fields": {"Dish ID": "madrid-besugo-al-horno", "Name": "Besugo al horno", "City ID": "madrid", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://realacademiadegastronomia.com/wp-content/uploads/2024/11/BESUGO-A-LA-MADRILENA.jpg", "Minutes": 45, "Ingredients": "200 g sea bream fillet\n180 g potatoes\n60 g onion\n1 lemon\n10 g olive oil\n1 garlic clove", "Steps": "Slice potatoes and onion thinly, toss with oil and bake at 190 °C until nearly tender.\nPlace the fish on top with garlic and lemon slices.\nReturn to the oven until the fish is opaque and flakes easily and the potatoes are cooked.", "Calories (kcal)": 490.0, "Protein (g)": 43.0, "Carbs (g)": 38.0, "Fat (g)": 18.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 44}}, {"fields": {"Dish ID": "madrid-sopa-de-ajo", "Name": "Sopa de ajo", "City ID": "madrid", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://i.pinimg.com/736x/dc/1e/2e/dc1e2e595cbb1da098df6b8cf98d3b34.jpg", "Minutes": 30, "Ingredients": "60 g day-old bread\n2 garlic cloves\n1 egg\n300 ml stock\n5 g paprika\n10 g olive oil", "Steps": "Slice garlic and gently soften in oil without burning it.\nAdd bread and paprika, stir briefly, then add stock and simmer for 15 minutes.\nCrack in the egg and simmer gently until cooked. Serve hot.", "Calories (kcal)": 370.0, "Protein (g)": 15.0, "Carbs (g)": 35.0, "Fat (g)": 18.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 45}}, {"fields": {"Dish ID": "madrid-soldaditos-de-pavia", "Name": "Soldaditos de Pavía", "City ID": "madrid", "Category": "Local Specialties", "Description": "A prepared local dish with a simplified prototype recipe.", "Image URL": "https://www.cocinayaficiones.com/wp-content/uploads/2023/05/soladitos-de-pavia.1.jpg", "Minutes": 35, "Ingredients": "180 g fully desalted cod\n50 g flour\n60 ml sparkling water\n100 g roasted red pepper\nOil for frying", "Steps": "Dry the fully desalted cod and cut into strips.\nWhisk flour and sparkling water into a light batter. Dip the fish in the batter.\nFry in hot oil in small batches until golden and cooked through. Drain and serve with roasted pepper strips.", "Calories (kcal)": 510.0, "Protein (g)": 36.0, "Carbs (g)": 42.0, "Fat (g)": 22.0, "Fiber (g)": 3.0, "Sugar (g)": 4.0, "Sodium (mg)": 650.0, "Order": 46}}, {"fields": {"Dish ID": "paris-savoury-cr-pe-galette-de-sarrasin", "Name": "Savoury crêpe (Galette de sarrasin)", "City ID": "paris", "Category": "Street Food", "Description": "Discover Savoury crêpe (Galette de sarrasin) in Paris. A simplified preparation is included below.", "Image URL": "https://img.over-blog-kiwi.com/1/60/79/78/20200626/ob_ef0178_img-8096.JPG", "Minutes": 25, "Ingredients": "50 g buckwheat flour\n100 ml water\n1 egg\n30 g cooked ham\n25 g Gruyère\n5 g butter", "Steps": "Whisk flour and water into a smooth batter.\nCook a thin galette in a buttered non-stick pan.\nAdd ham, cheese and the egg.\nFold the edges inward and cook gently until the egg is set and the filling is hot.", "Calories (kcal)": 460.0, "Protein (g)": 27.0, "Carbs (g)": 37.0, "Fat (g)": 22.0, "Fiber (g)": 4.0, "Sugar (g)": 2.0, "Sodium (mg)": 680.0, "Order": 47}}, {"fields": {"Dish ID": "paris-jambon-beurre", "Name": "Jambon-Beurre", "City ID": "paris", "Category": "Street Food", "Description": "Discover Jambon-Beurre in Paris. A simplified preparation is included below.", "Image URL": "https://media.timeout.com/images/106405462/750/562/image.jpg", "Minutes": 5, "Ingredients": "100 g baguette\n50 g cooked ham\n15 g butter", "Steps": "Split the baguette lengthways and spread with butter.\nAdd the ham, close the sandwich and serve.", "Calories (kcal)": 440.0, "Protein (g)": 19.0, "Carbs (g)": 57.0, "Fat (g)": 16.0, "Fiber (g)": 3.0, "Sugar (g)": 3.0, "Sodium (mg)": 1050.0, "Order": 48}}, {"fields": {"Dish ID": "paris-quiche-lorraine", "Name": "Quiche Lorraine", "City ID": "paris", "Category": "Street Food", "Description": "Discover Quiche Lorraine in Paris. A simplified preparation is included below.", "Image URL": "https://i0.wp.com/www.pardonyourfrench.com/wp-content/uploads/2018/04/Classic-French-Quiche-Lorraine-2.jpg?resize=1170%2C1753&ssl=1", "Minutes": 50, "Ingredients": "70 g shortcrust pastry\n1 egg\n40 ml cream\n30 g bacon\nA pinch of nutmeg", "Steps": "Line a small tart tin with pastry and blind-bake at 180 °C for 10 minutes.\nCook and drain the bacon.\nWhisk egg and cream with nutmeg, add bacon and pour into the shell.\nBake for about 25 minutes until the filling is set.", "Calories (kcal)": 590.0, "Protein (g)": 18.0, "Carbs (g)": 38.0, "Fat (g)": 41.0, "Fiber (g)": 2.0, "Sugar (g)": 3.0, "Sodium (mg)": 700.0, "Order": 49}}, {"fields": {"Dish ID": "paris-soupe-l-oignon", "Name": "Soupe à l'oignon", "City ID": "paris", "Category": "Main Dishes", "Description": "Discover Soupe à l'oignon in Paris. A simplified preparation is included below.", "Image URL": "https://www.pariszigzag.fr/wp-content/uploads/2024/05/soupe-a-loignon.webp", "Minutes": 55, "Ingredients": "200 g onions\n10 g butter\n250 ml stock\n40 g bread\n30 g Gruyère", "Steps": "Slice onions and cook slowly in butter until deeply golden, about 30 minutes.\nAdd stock and simmer for 15 minutes.\nPour into an ovenproof bowl, top with toasted bread and cheese and grill until bubbling.", "Calories (kcal)": 390.0, "Protein (g)": 16.0, "Carbs (g)": 41.0, "Fat (g)": 18.0, "Fiber (g)": 5.0, "Sugar (g)": 12.0, "Sodium (mg)": 950.0, "Order": 50}}]}
