{"typecast": true, "records": [{"fields": {"Dish ID": "paris-boeuf-bourguignon", "Name": "Boeuf Bourguignon", "City ID": "paris", "Category": "Main Dishes", "Description": "Discover Boeuf Bourguignon in Paris. A simplified preparation is included below.", "Image URL": "https://www.cia-france.it/media/3104/boeuf-bourguignon-recette-traditionnellejpg_1000x700.jpg", "Minutes": 180, "Ingredients": "150 g stewing beef\n50 g carrots\n50 g mushrooms\n40 g onion\n75 ml red wine\n100 ml stock\n10 g oil", "Steps": "Brown the beef in oil, add chopped onion and carrot, then pour in wine and stock.\nSimmer gently for about 2½ hours until tender, adding water if needed.\nAdd mushrooms for the final 20 minutes.", "Calories (kcal)": 480.0, "Protein (g)": 37.0, "Carbs (g)": 15.0, "Fat (g)": 26.0, "Fiber (g)": 4.0, "Sugar (g)": 7.0, "Sodium (mg)": 560.0, "Order": 51}}, {"fields": {"Dish ID": "paris-duck-confit", "Name": "Duck Confit", "City ID": "paris", "Category": "Main Dishes", "Description": "Discover Duck Confit in Paris. A simplified preparation is included below.", "Image URL": "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSwUsE4RZTpwDJAc9UO_TIi5W5hXQrX-USjkhgWc_NaxHw84pb7x8xm3CTT&s=10", "Minutes": 40, "Ingredients": "1 ready-cooked duck confit leg\n150 g potatoes\n80 g green beans", "Steps": "Follow the package instructions to heat the ready-cooked confit leg until piping hot and crisp-skinned.\nRoast the potatoes in a little fat from the duck and cook the beans separately.\nServe together; this shortcut does not reproduce the curing process.", "Calories (kcal)": 720.0, "Protein (g)": 43.0, "Carbs (g)": 35.0, "Fat (g)": 45.0, "Fiber (g)": 6.0, "Sugar (g)": 4.0, "Sodium (mg)": 1050.0, "Order": 52}}, {"fields": {"Dish ID": "paris-escargots-de-bourgogne", "Name": "Escargots de Bourgogne", "City ID": "paris", "Category": "Main Dishes", "Description": "Discover Escargots de Bourgogne in Paris. A simplified preparation is included below.", "Image URL": "https://media-cdn.tripadvisor.com/media/photo-s/1a/dc/60/af/escargots-de-bourgogne.jpg", "Minutes": 20, "Ingredients": "12 prepared food-grade cooked snails\n20 g butter\nGarlic and parsley\n40 g bread", "Steps": "Use prepared cooked snails and follow their package instructions.\nMix softened butter with finely chopped garlic and parsley.\nArrange snails in a suitable ovenproof dish, add butter and bake until piping hot.\nServe with bread.", "Calories (kcal)": 310.0, "Protein (g)": 20.0, "Carbs (g)": 24.0, "Fat (g)": 16.0, "Fiber (g)": 2.0, "Sugar (g)": 2.0, "Sodium (mg)": 380.0, "Order": 53}}, {"fields": {"Dish ID": "paris-croissant-au-beurre", "Name": "Croissant au beurre", "City ID": "paris", "Category": "Sweets", "Description": "Discover Croissant au beurre in Paris. A simplified preparation is included below.", "Image URL": "https://jeffreycagnes.fr/cdn/shop/files/croissant-beurre-viennoiserie-paris-jeffrey-cagnes.webp?v=1784122551&width=2500", "Minutes": 20, "Ingredients": "1 ready-to-bake butter croissant, about 65 g", "Steps": "Use a ready-shaped butter croissant and follow the package proofing instructions if required.\nBake according to the package until risen and golden.\nTypical ingredients include wheat flour, butter, milk, yeast, sugar and salt; check the label.", "Calories (kcal)": 280.0, "Protein (g)": 6.0, "Carbs (g)": 30.0, "Fat (g)": 15.0, "Fiber (g)": 2.0, "Sugar (g)": 7.0, "Sodium (mg)": 310.0, "Order": 54}}, {"fields": {"Dish ID": "paris-pain-au-chocolat", "Name": "Pain au chocolat", "City ID": "paris", "Category": "Sweets", "Description": "Discover Pain au chocolat in Paris. A simplified preparation is included below.", "Image URL": "https://cdn.tasteatlas.com/images/dishes/259a7f803c4c4cdd9ba0a67203b5c00f.jpg?w=600&h=450", "Minutes": 20, "Ingredients": "1 ready-to-bake pain au chocolat, about 75 g", "Steps": "Use a ready-shaped pastry and follow its package proofing instructions if required.\nBake according to the package until golden.\nTypical ingredients include wheat flour, butter, chocolate, milk, yeast, sugar and salt; check the label.", "Calories (kcal)": 340.0, "Protein (g)": 6.0, "Carbs (g)": 37.0, "Fat (g)": 19.0, "Fiber (g)": 3.0, "Sugar (g)": 13.0, "Sodium (mg)": 300.0, "Order": 55}}, {"fields": {"Dish ID": "paris-macarons", "Name": "Macarons", "City ID": "paris", "Category": "Sweets", "Description": "Discover Macarons in Paris. A simplified preparation is included below.", "Image URL": "https://www.madaboutmacarons.com/wp-content/uploads/2022/05/laduree-macarons-paris-flavours.jpg", "Minutes": 65, "Ingredients": "25 g ground almonds\n30 g icing sugar\n20 g egg white\n15 g caster sugar\n20 g chocolate ganache", "Steps": "Sift almonds and icing sugar.\nWhisk egg white with caster sugar to stiff peaks, then fold in the dry ingredients until the mixture flows slowly.\nPipe small rounds, rest until a skin forms and bake at 150 °C for about 14 minutes.\nCool and sandwich with ganache; makes a small serving of several macarons.", "Calories (kcal)": 390.0, "Protein (g)": 8.0, "Carbs (g)": 49.0, "Fat (g)": 18.0, "Fiber (g)": 3.0, "Sugar (g)": 43.0, "Sodium (mg)": 70.0, "Order": 56}}, {"fields": {"Dish ID": "paris-clair-au-chocolat", "Name": "Éclair au chocolat", "City ID": "paris", "Category": "Sweets", "Description": "Discover Éclair au chocolat in Paris. A simplified preparation is included below.", "Image URL": "https://cache.marieclaire.fr/data/photo/w1000_ci/7a/recette-eclair-chocolat-inratable.jpg", "Minutes": 55, "Ingredients": "25 g flour\n40 ml water\n15 g butter\n1 small egg\n50 g prepared pastry cream\n20 g dark chocolate", "Steps": "Boil water and butter, stir in flour and cook briefly.\nCool slightly, beat in egg gradually, pipe a short éclair and bake at 200 °C until puffed, then at 180 °C until dry.\nCool completely, fill with prepared pastry cream and glaze with melted chocolate.", "Calories (kcal)": 400.0, "Protein (g)": 10.0, "Carbs (g)": 34.0, "Fat (g)": 25.0, "Fiber (g)": 2.0, "Sugar (g)": 18.0, "So