// MARK: - Airtable (live data)
// Cities and dishes come from Airtable (base "App Cibi", tables "Cities" and "Dishes").
// If Airtable can't be reached, the app uses the last downloaded copy; on a first
// launch without internet it falls back to the bundled data above. The UI is unchanged.

extension SampleData {
    static var cities: [City] { EatravelAirtable.cities ?? bundledCities }
    static var dishes: [Dish] { EatravelAirtable.dishes ?? bundledDishes }
}

enum EatravelAirtable {
    // ⚠️ Test only: a token inside the app can be extracted by anyone who has the app.
    static let token = "__TOKEN__"
    static let baseID = "__BASE__"

    private(set) static var cities: [City]?
    private(set) static var dishes: [Dish]?
    private static var coordinates: [String: (latitude: Double, longitude: Double)] = [:]

    static func coordinate(for cityID: String) -> (latitude: Double, longitude: Double)? {
        coordinates[cityID]
    }

    /// Called once at launch, before the first screen appears.
    @MainActor
    static func load() async {
        if let snapshot = try? await download(), apply(snapshot) {
            save(snapshot)
        } else if let cached = readCache() {
            _ = apply(cached)
        }
    }

    // MARK: Airtable records

    private struct Snapshot: Codable {
        let cities: [Record<CityFields>]
        let dishes: [Record<DishFields>]
    }

    private struct Page<F: Codable>: Codable {
        let records: [Record<F>]
        let offset: String?
    }

    private struct Record<F: Codable>: Codable {
        let id: String
        let fields: F
    }

    private struct CityFields: Codable {
        var cityID: String?
        var name: String?
        var country: String?
        var subtitle: String?
        var imageURL: String?
        var latitude: Double?
        var longitude: Double?
        enum CodingKeys: String, CodingKey {
            case cityID = "City ID", name = "Name", country = "Country", subtitle = "Subtitle"
            case imageURL = "Image URL", latitude = "Latitude", longitude = "Longitude"
        }
    }

    private struct DishFields: Codable {
        var dishID: String?
        var name: String?
        var cityID: String?
        var category: String?
        var description: String?
        var photo: [Attachment]?
        var imageURL: String?
        var minutes: Double?
        var ingredients: String?
        var steps: String?
        var calories: Double?
        var protein: Double?
        var carbs: Double?
        var fat: Double?
        var fiber: Double?
        var sugar: Double?
        var sodium: Double?
        enum CodingKeys: String, CodingKey {
            case dishID = "Dish ID", name = "Name", cityID = "City ID", category = "Category"
            case description = "Description", photo = "Photo", imageURL = "Image URL"
            case minutes = "Minutes", ingredients = "Ingredients", steps = "Steps"
            case calories = "Calories (kcal)", protein = "Protein (g)", carbs = "Carbs (g)"
            case fat = "Fat (g)", fiber = "Fiber (g)", sugar = "Sugar (g)", sodium = "Sodium (mg)"
        }
    }

    private struct Attachment: Codable {
        let url: String
    }

    // MARK: Network

    private static func download() async throws -> Snapshot {
        async let cities = fetchAll("Cities", as: CityFields.self)
        async let dishes = fetchAll("Dishes", as: DishFields.self)
        return try await Snapshot(cities: cities, dishes: dishes)
    }

    private static func fetchAll<F: Codable>(_ table: String, as type: F.Type) async throws -> [Record<F>] {
        var all: [Record<F>] = []
        var offset: String?
        repeat {
            var components = URLComponents(string: "https://api.airtable.com/v0/\(baseID)/\(table)")!
            var query = [URLQueryItem(name: "pageSize", value: "100"),
                         URLQueryItem(name: "sort[0][field]", value: "Order"),
                         URLQueryItem(name: "sort[0][direction]", value: "asc")]
            if let offset { query.append(URLQueryItem(name: "offset", value: offset)) }
            components.queryItems = query
            var request = URLRequest(url: components.url!, timeoutInterval: 10)
            request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")
            let (data, response) = try await URLSession.shared.data(for: request)
            guard (response as? HTTPURLResponse)?.statusCode == 200 else {
                throw URLError(.badServerResponse)
            }
            let page = try JSONDecoder().decode(Page<F>.self, from: data)
            all += page.records
            offset = page.offset
        } while offset != nil
        return all
    }

    // MARK: Conversion to the app's models

    @MainActor
    private static func apply(_ snapshot: Snapshot) -> Bool {
        var newCoordinates: [String: (latitude: Double, longitude: Double)] = [:]
        let newCities: [City] = snapshot.cities.compactMap { record in
            let f = record.fields
            guard let id = clean(f.cityID), let name = clean(f.name) else { return nil }
            if let lat = f.latitude, let lon = f.longitude { newCoordinates[id] = (lat, lon) }
            return City(id: id, name: name, country: f.country ?? "", subtitle: f.subtitle ?? "",
                        image: f.imageURL ?? "")
        }
        let newDishes: [Dish] = snapshot.dishes.compactMap { record in
            let f = record.fields
            guard let name = clean(f.name), let cityID = clean(f.cityID),
                  let category = category(f.category) else { return nil }
            return Dish(id: clean(f.dishID) ?? record.id,
                        cityID: cityID,
                        category: category,
                        name: name,
                        description: f.description ?? "",
                        image: f.photo?.first?.url ?? f.imageURL ?? "",
                        minutes: Int((f.minutes ?? 0).rounded()),
                        ingredients: lines(f.ingredients),
                        steps: lines(f.steps),
                        nutrition: Nutrition(calories: int(f.calories), protein: int(f.protein),
                                             carbs: int(f.carbs), fat: int(f.fat),
                                             fiber: f.fiber ?? 0, sugar: f.sugar ?? 0,
                                             sodium: int(f.sodium)))
        }
        guard !newCities.isEmpty, !newDishes.isEmpty else { return false }
        cities = newCities
        dishes = newDishes
        coordinates = newCoordinates
        return true
    }

    private static func category(_ label: String?) -> FoodCategory? {
        guard let label = clean(label) else { return nil }
        switch label {
        case "Street Food": .streetFood
        case "Main Dishes": .mains
        case "Sweets": .sweets
        case "Local Specialties": .specialties
        default: nil
        }
    }

    private static func clean(_ text: String?) -> String? {
        guard let t = text?.trimmingCharacters(in: .whitespacesAndNewlines), !t.isEmpty else { return nil }
        return t
    }

    private static func lines(_ text: String?) -> [String] {
        (text ?? "").split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
    }

    private static func int(_ value: Double?) -> Int { Int((value ?? 0).rounded()) }

    // MARK: Offline copy

    private static var cacheURL: URL {
        FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("eatravel-airtable-v1.json")
    }

    private static func save(_ snapshot: Snapshot) {
        if let data = try? JSONEncoder().encode(snapshot) { try? data.write(to: cacheURL, options: .atomic) }
    }

    private static func readCache() -> Snapshot? {
        guard let data = try? Data(contentsOf: cacheURL) else { return nil }
        return try? JSONDecoder().decode(Snapshot.self, from: data)
    }
}

EATRAVEL_EOF
cat > "$TMP/app_append.swift" << 'EATRAVEL_EOF'

/// Loads cities and dishes from Airtable before showing the first screen.
/// While loading, only the app's background colour is visible.
struct AirtableGate<Content: View>: View {
    @ViewBuilder let content: () -> Content
    @State private var ready = false

    var body: some View {
        if ready {
            content()
        } else {
            EatravelStyle.background
                .ignoresSafeArea()
                .task {
                    await EatravelAirtable.load()
                    ready = true
                }
        }
    }
}

EATRAVEL_EOF


api() {  # $1 metodo, $2 url, $3 file JSON (opzionale)
  if [ -n "$3" ]; then
    HTTP=$(curl -s -o "$TMP/out.json" -w "%{http_code}" -X "$1" "$2" -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" --data @"$3")
  else
    HTTP=$(curl -s -o "$TMP/out.json" -w "%{http_code}" -X "$1" "$2" -H "Authorization: Bearer $TOKEN")
  fi
}
fail() { echo "❌ $1 (errore $HTTP):"; cat "$TMP/out.json"; echo ""; rm -rf "$TMP"; exit 1; }

# ---------- 3. Tabelle e dati in Airtable ----------
prepara_tabella() {  # $1 nome tabella, $2 prefisso file
  api GET "https://api.airtable.com/v0/$BASE_ID/$1?maxRecords=1"
  if [ "$HTTP" = "200" ]; then
    if grep -q '"id"' "$TMP/out.json"; then
      echo "✅ Tabella $1 già presente con dati: la lascio com'è."; return
    fi
  else
    echo "→ Creo la tabella $1..."
    api POST "https://api.airtable.com/v0/meta/bases/$BASE_ID/tables" "$TMP/t_$2.json"
    [ "$HTTP" -ge 300 ] && fail "Non riesco a creare la tabella $1"
  fi
  echo "→ Inserisco i dati in $1..."
  for f in "$TMP"/r_$2_*.json; do
    api POST "https://api.airtable.com/v0/$BASE_ID/$1" "$f"
    [ "$HTTP" -ge 300 ] && fail "Errore inserendo i dati in $1"
    printf "."; sleep 0.3
  done
  echo ""; echo "✅ $1 pronta."
}
prepara_tabella Cities cities
prepara_tabella Dishes dishes

# ---------- 4. Collega l'app (interfaccia invariata) ----------
if grep -q "bundledCities" "$SRC/SampleData.swift"; then
  echo "✅ Il codice dell'app è già collegato ad Airtable."
else
  BACKUP="$PROJ/Eatravel_backup_$(date +%Y%m%d-%H%M%S)"
  cp -R "$SRC" "$BACKUP"
  echo "✅ Copia di sicurezza: $BACKUP"

  perl -0pi -e 's/static let cities: \[City\] = \[/static let bundledCities: [City] = [/; s/static let dishes: \[Dish\] = \[/static let bundledDishes: [Dish] = [/' "$SRC/SampleData.swift"
  perl -pi -e "s/__TOKEN__/$TOKEN/; s/__BASE__/$BASE_ID/" "$TMP/sampledata_append.swift"
  cat "$TMP/sampledata_append.swift" >> "$SRC/SampleData.swift"

  perl -0pi -e 's/^(\s*)CitySelectionView\(\)$/$1AirtableGate { CitySelectionView() }/m' "$SRC/EatravelApp.swift"
  cat "$TMP/app_append.swift" >> "$SRC/EatravelApp.swift"

  perl -0pi -e 's/let coordinate = Self\.cityCoordinates\[city\.id\] \{/let coordinate = (EatravelAirtable.coordinate(for: city.id).map({ CLLocationCoordinate2D(latitude: \$0.latitude, longitude: \$0.longitude) }) ?? Self.cityCoordinates[city.id]) {/' "$SRC/DishMapView.swift"

  OK=1
  grep -q "static let bundledCities" "$SRC/SampleData.swift" || OK=0
  grep -q "static let bundledDishes" "$SRC/SampleData.swift" || OK=0
  grep -q "AirtableGate { CitySelectionView() }" "$SRC/EatravelApp.swift" || OK=0
  grep -q "EatravelAirtable.coordinate" "$SRC/DishMapView.swift" || OK=0
  if [ $OK -eq 0 ]; then
    rm -rf "$SRC"; cp -R "$BACKUP" "$SRC"
    echo "❌ Il codice non è come mi aspettavo: ho ripristinato i file originali. Manda uno screenshot a Claude."
    rm -rf "$TMP"; exit 1
  fi
  echo "✅ App collegata ad Airtable (modificati: SampleData.swift, EatravelApp.swift, DishMapView.swift)."
fi

